import React from 'react';
import { useNavigate } from 'react-router-dom';

const Dashboard = () => {
  const navigate = useNavigate();

  const handleLogout = () => {
    alert("Logged out successfully");
    navigate('/'); // العودة لصفحة تسجيل الدخول
  };

  return (
    <div style={{ padding: '40px', textAlign: 'center', fontFamily: 'Arial' }}>
      <h1>مرحباً بك في Stag.io</h1>
      <p>لقد تم تسجيل دخولك بنجاح باستخدام بريدك الجامعي.</p>
      <div style={{ 
        marginTop: '20px', 
        padding: '20px', 
        backgroundColor: '#ebf8ff', 
        borderRadius: '8px',
        display: 'inline-block' 
      }}>
        <h3>لوحة التحكم الخاصة بالطالب</h3>
        <p>هنا ستظهر قائمة طلبات التربص الخاصة بك قريباً.</p>
      </div>
      <br />
      <button 
        onClick={handleLogout}
        style={{ 
          marginTop: '20px', 
          padding: '10px 20px', 
          backgroundColor: '#c5a3d1', 
          color: 'white', 
          border: 'none', 
          borderRadius: '5px', 
          cursor: 'pointer' 
        }}
      >
        تسجيل الخروج
      </button>
    </div>
  );
};

export default Dashboard;
